{"script":"const links = Array.from(document.querySelectorAll('a[aria-label*="6"]'));
const results = links.map((l, i) => ({
  index: i,
  text: l.textContent.trim(),
  ariaLabel: l.getAttribute('aria-label'),
  href: l.getAttribute('href')
})).filter(r => r.ariaLabel && (r.ariaLabel.includes('size 6') || r.ariaLabel.includes('Shoe Size 6') || r.ariaLabel === 'Apply 6 filter to narrow results'));
return results;
"}

